import {createMusicClock} from './shared/music-clock.js';
let warSoundAt=0;
import {DB} from './data.js';
let ac,master,sfx,music,analyser;let notes=0,backgroundSuspended=false;
export function audio(){if(!ac){ac=new (window.AudioContext||window.webkitAudioContext)({latencyHint:'interactive'});master=ac.createGain();master.connect(ac.destination);sfx=ac.createGain();sfx.connect(master);music=ac.createGain();music.connect(master);analyser=ac.createAnalyser();analyser.fftSize=256;analyser.connect(master);applyAudio();}if(ac.state==='suspended'&&!globalThis.document?.hidden)ac.resume()?.then?.(()=>clock.sync(),()=>{});else clock.sync();return ac;}
export function output(){audio();return analyser;}
export function applyAudio(){if(!ac)return;master.gain.setTargetAtTime(DB.settings.muted||globalThis.document?.hidden?0:1,ac.currentTime,.02);sfx.gain.setTargetAtTime((DB.settings.sound/100)*.32,ac.currentTime,.02);music.gain.setTargetAtTime(backgroundSuspended?0:(DB.settings.music/100)*.1,ac.currentTime,.02);if(DB.settings.muted)stopVoices();clock.sync();}
const voices=new Set();
function stopVoices(){for(const voice of voices){try{voice.stop();}catch{}}voices.clear();}
const clock=createMusicClock({getState:()=>({...DB.settings,backgroundSuspended,ready:!!ac&&ac.state==='running'}),onBeat:()=>{const seq=[220,277.18,329.63,440,329.63,277.18,246.94,329.63];tone(seq[notes++%seq.length],.32,'sine',music,.4);},onQuiet:(force=false)=>{if(!ac)return;if(force||globalThis.document?.hidden)stopVoices();master.gain.setTargetAtTime(force||globalThis.document?.hidden||DB.settings.muted?0:1,ac.currentTime,.02);}});

function tone(freq,len=.1,type='sine',dest=sfx,vol=1,when){if(globalThis.document?.hidden||DB.settings.muted)return;let a=audio(),o=a.createOscillator(),g=a.createGain(),t=when??a.currentTime;o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(Math.max(.001,vol),t+.006);g.gain.exponentialRampToValueAtTime(.001,t+len);o.connect(g);g.connect(dest||sfx);voices.add(o);o.start(t);o.stop(t+len+.02);o.onended=()=>{voices.delete(o);o.disconnect();g.disconnect();};}
let lastGameSound=-1,lastColorSound=-1,lastColorKind='',lastTapSound=-1;
export function fx(kind='tap'){if(DB.settings.muted||globalThis.document?.hidden)return;audio();if(kind.startsWith('war-')){if(ac.currentTime-warSoundAt<.085)return;warSoundAt=ac.currentTime;const n={'war-step':100,'war-sword':600,'war-heavy':85,'war-bow':750,'war-cannon':55,'war-magic':440,'war-block':1250}[kind]||250;tone(n,kind==='war-cannon'?.25:.09,kind==='war-block'?'sine':'triangle',sfx,kind==='war-step'?.025:.12);if(kind==='war-magic')tone(880,.15,'sine',sfx,.06,ac.currentTime+.04);return;}if(kind==='buddy-react'){[260,390,310,540].forEach((n,i)=>tone(n,.1,'triangle',sfx,.13,ac.currentTime+i*.055));return;}if(kind==='repair-good'){tone(740,.07,'sine',sfx,.15);tone(1110,.12,'triangle',sfx,.13,ac.currentTime+.07);return;}if(kind==='doodle-ink'){tone(330,.06,'triangle',sfx,.1);tone(470,.04,'sine',sfx,.12,ac.currentTime+.04);return;}if(kind==='gravity-flip'){tone(430,.11,'sine',sfx,.18);tone(650,.11,'triangle',sfx,.12,ac.currentTime+.06);return;}if(kind==='gravity-impact'){tone(190,.055,'triangle',sfx,.16);return;}if(kind==='slime-bounce'){tone(210,.12,'sine',sfx,.24);tone(340,.13,'sine',sfx,.15,ac.currentTime+.05);return;}if(kind==='dental-sparkle'){tone(1200,.1,'sine',sfx,.16);tone(1800,.12,'sine',sfx,.1,ac.currentTime+.08);return;}if(kind==='secret'){[440,660,330,880].forEach((n,i)=>tone(n,.15,'triangle',sfx,.25,ac.currentTime+i*.09));return;}if(kind==='chew'){tone(135,.09,'triangle',sfx,.23);tone(215,.07,'square',sfx,.05,ac.currentTime+.04);return;}if(kind==='swallow'){tone(170,.18,'sine',sfx,.22);tone(90,.13,'sine',sfx,.18,ac.currentTime+.06);return;}if(kind==='launch-food'){tone(420,.08,'triangle',sfx,.14);return;}if(kind.startsWith('color-')){if(kind===lastColorKind&&ac.currentTime-lastColorSound<.08)return;lastColorKind=kind;lastColorSound=ac.currentTime;const n=Number(kind.slice(6))||0;tone(580+n*85,.16,'sine',sfx,.32);tone(870+n*85,.2,'sine',sfx,.25,ac.currentTime+.12);return;}if(['signal','goal','save','treasure','wave','kick','dig','crowd'].includes(kind)){if(ac.currentTime-lastGameSound<.055)return;lastGameSound=ac.currentTime;if(kind==='goal'||kind==='treasure'){[523,659,784].forEach((n,i)=>tone(n,.2,'triangle',sfx,.28,ac.currentTime+i*.07));}else if(kind==='kick'||kind==='dig')tone(kind==='kick'?100:160,.09,'triangle',sfx,.25);else if(kind==='crowd'){[174,220,261,329].forEach((n,i)=>tone(n,.35,'triangle',sfx,.08,ac.currentTime+i*.035));}else tone(kind==='signal'?1150:kind==='save'?780:660,.2,'sine',sfx,.3);return;}if(kind.startsWith('smash-')){const material=kind.slice(6);if(material==='explosive'){tone(65,.4,'sawtooth',sfx,.23);tone(110,.24,'triangle',sfx,.3);}else if(material==='glass'||material==='ice'){tone(material==='glass'?1900:1350,.12,'sine',sfx,.22);tone(2650,.09,'triangle',sfx,.09,ac.currentTime+.025);}else if(material==='metal'){tone(420,.18,'triangle',sfx,.24);tone(635,.23,'sine',sfx,.11);}else{tone(material==='wood'?170:110,.12,'triangle',sfx,.27);tone(85,.1,'sine',sfx,.12);}return;}if(['hit','bad'].includes(kind)){if(ac.currentTime-lastTapSound<.04)return;lastTapSound=ac.currentTime;}if(kind==='bad')tone(130,.16,'triangle',sfx,.3);else if(kind==='count')tone(330,.12,'square',sfx,.12);else if(kind==='go'){tone(880,.22,'sine',sfx,.35);tone(1320,.25,'sine',sfx,.2,ac.currentTime+.05);}else if(['win','record','achievement'].includes(kind)){[523,659,784,1047].forEach((n,i)=>tone(n,.3,'triangle',sfx,.3,ac.currentTime+i*.1));}else tone(kind==='hit'?640:450,.07,'sine',sfx,.18);}
export function metronome(when,accent=false){audio();tone(accent?1600:1100,.035,'sine',sfx,.25,when);}
export function muteBackground(v){backgroundSuspended=v;clock.sync();if(music)music.gain.setTargetAtTime(v?0:(DB.settings.music/100)*.1,ac.currentTime,.03);}
export function spectrum(){if(!analyser)return new Uint8Array(128);let b=new Uint8Array(analyser.frequencyBinCount);analyser.getByteFrequencyData(b);return b;}
